def eta(a,b):
    if a==b:return 0.
    return 1-b/a if b<a else 1-(1-b)/(1-a)
def urow(a,b,wa,wb):
    return min(wa*eta(x,a)+wb*eta(x,b) for x in (0.,1.,a,b))
def unfair(x1,x2):
    return urow(x1,x2,1/3,1/6)+urow(2*x1-.5,.5*x2,1/6,1/3)
print('Lemma 7.3 check: a=b=.2, c=d=.1, beta=.5; its D bound is zero.')
f=lambda x:.5*eta(.2+.2*x,.1+.1*x)+.5*(1-(.1+.1*x))
print('psi(0), psi(1), finite difference:', f(0),f(1),f(1)-f(0))
print('Figure 1 inputs: minimum unfairness at fixed error, from a dense feasible search:')
for e in (1/12,.12,1/6,.20,.22,.25):
    low=max(.25,(3*(e+1/12)-1)/2)
    high=min(.75,3*(e+1/12)/2)
    best=(1,None,None)
    for i in range(20001):
        x1=low+(high-low)*i/20000
        x2=3*(e+1/12)-2*x1
        if not(0<=x2<=1):continue
        u=unfair(x1,x2)
        if u<best[0]:best=(u,x1,x2)
    print({'error':e,'best_unfairness':best[0],'rates':best[1:],'endpoint_chord_unfairness':(.25-e)/2})
